CREATE TABLE payments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),booking_id UUID NOT NULL REFERENCES scheduled_bookings(id),payer_user_id UUID REFERENCES users(id),amount_minor BIGINT NOT NULL,currency CHAR(3) NOT NULL,method VARCHAR(24) NOT NULL,status VARCHAR(24) NOT NULL,provider VARCHAR(32),provider_payment_id VARCHAR(128),idempotency_key VARCHAR(128) UNIQUE NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE cancellation_policy_versions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),scope_type VARCHAR(24) NOT NULL,version_no INT NOT NULL,free_until_minutes INT NOT NULL,mid_window_from_minutes INT NOT NULL,mid_fee_bps INT NOT NULL,late_fee_bps INT NOT NULL,no_show_fee_bps INT NOT NULL,status VARCHAR(20) NOT NULL,effective_from TIMESTAMPTZ);
CREATE TABLE cancellation_charges(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),booking_id UUID NOT NULL REFERENCES scheduled_bookings(id),policy_id UUID NOT NULL REFERENCES cancellation_policy_versions(id),charged_amount_minor BIGINT NOT NULL,driver_compensation_minor BIGINT NOT NULL,platform_amount_minor BIGINT NOT NULL,currency CHAR(3) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE ride_ratings(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),booking_id UUID NOT NULL REFERENCES scheduled_bookings(id),rater_id UUID NOT NULL REFERENCES users(id),rated_user_id UUID NOT NULL REFERENCES users(id),score SMALLINT NOT NULL CHECK(score BETWEEN 1 AND 5),comment VARCHAR(1000),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(booking_id,rater_id));
CREATE TABLE notifications(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID REFERENCES users(id),event_type VARCHAR(128) NOT NULL,channel VARCHAR(16) NOT NULL,template_code VARCHAR(80) NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'PENDING',dedupe_key VARCHAR(160) UNIQUE,data JSONB NOT NULL DEFAULT '{}'::jsonb,scheduled_for TIMESTAMPTZ,sent_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
